// Fills in the install snippet (generated by `npm run build` into snippet.json) and checks the hosted client is reachable.
(async () => {
  const $ = id => document.getElementById(id);
  let info;
  try { info = await (await fetch('snippet.json', { cache: 'no-store' })).json(); }
  catch { $('snippet').textContent = 'snippet.json is missing - run "npm run build" (see docs/DEPLOYMENT.md).'; $('reach').textContent = ''; return; }
  $('snippet').textContent = info.snippet;
  $('clientUrl').textContent = info.clientUrl;
  $('bookmarklet').href = 'javascript:' + encodeURIComponent(info.snippet);
  $('bookmarklet').addEventListener('click', e => { e.preventDefault(); alert('Drag this button to your bookmarks bar instead of clicking it here.'); });
  $('copy').addEventListener('click', async () => {
    try { await navigator.clipboard.writeText(info.snippet); }
    catch { const r = document.createRange(); r.selectNodeContents($('snippet')); const s = getSelection(); s.removeAllRanges(); s.addRange(r); document.execCommand('copy'); }
    $('copy').textContent = 'Copied ✓'; $('copied').hidden = false; setTimeout(() => { $('copy').textContent = 'Copy'; }, 2500);
  });
  try {
    const r = await fetch(info.clientUrl, { cache: 'no-store' });
    const t = await r.text();
    if (!r.ok || !/Infinite Craft Multiplayer/.test(t)) throw new Error('unexpected response');
    $('reach').textContent = '✓ Multiplayer script is online and reachable from your network.'; $('reach').className = 'status ok';
  } catch (e) { $('reach').textContent = '✗ Could not reach the multiplayer script from this network (' + e.message + '). The snippet will not work here - see "School or work computers".'; $('reach').className = 'status bad'; }
})();
